import { expect, test } from "bun:test";

import { isRetryBranch, parseRoundBranch, summarizeRounds } from "../src/rounds.ts";

test("parseRoundBranch reads agent/rounds-N", () => {
  expect(parseRoundBranch("agent/rounds-1")).toBe(1);
  expect(parseRoundBranch("agent/rounds-12")).toBe(12);
  expect(parseRoundBranch("agent/rounds-0")).toBeNull();
  expect(parseRoundBranch("agent/rounds-2-retry")).toBeNull();
});

test("isRetryBranch matches -retry suffixed branches", () => {
  expect(isRetryBranch("agent/rounds-2-retry")).toBe(true);
  expect(isRetryBranch("agent/rounds-2")).toBe(false);
});

test("summarizeRounds counts rounds, retries and max", () => {
  expect(summarizeRounds(["agent/rounds-1", "agent/rounds-2", "agent/rounds-2-retry"])).toEqual({
    rounds: 2,
    retries: 1,
    max_round: 2,
  });
});
